<?php
namespace App\Http\Controllers;
use App\Http\Requests\TenderRequest; use App\Models\Institution; use App\Models\Tender; use App\Services\ProcessExportService; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Inertia\Inertia; use Inertia\Response;
class TenderController extends Controller { public function index(Request $request): Response { $this->authorize('viewAny',Tender::class); return Inertia::render('Tenders',['records'=>$this->filtered($request)->with('institution:id,name')->paginate(20)->withQueryString(),'institutions'=>Institution::orderBy('name')->get(['id','name']),'filters'=>$request->only('search','status','purchase_type')]); } public function store(TenderRequest $request): RedirectResponse { $this->authorize('create',Tender::class); Tender::create([...$request->validated(),'owner_id'=>$request->user()->id]); return back()->with('success','Licitación creada.'); } public function update(TenderRequest $request,Tender $tender): RedirectResponse { $this->authorize('update',$tender); $tender->update($request->validated()); return back()->with('success','Licitación actualizada.'); } public function destroy(Tender $tender): RedirectResponse { $this->authorize('delete',$tender); $tender->delete(); return back()->with('success','Licitación eliminada.'); } public function pdf(Request $request, ProcessExportService $exports) { $this->authorize('viewAny', Tender::class); return $exports->pdf('Licitaciones', $this->filtered($request)->with('institution:id,name')->get()); } public function xlsx(Request $request, ProcessExportService $exports) { $this->authorize('viewAny', Tender::class); return $exports->spreadsheet($this->filtered($request)->with('institution:id,name')->get(), 'licitaciones.xlsx'); } private function filtered(Request $request) { $q=Tender::query()->latest('published_at'); if(!$request->user()->isAdmin())$q->where('owner_id',$request->user()->id); if($s=$request->string('search')->trim()->value())$q->where(fn($x)=>$x->where('reference','like',"%$s%")->orWhere('title','like',"%$s%")); foreach(['status','purchase_type'] as $f)if($request->filled($f))$q->where($f,$request->string($f)); return $q; } }
